/* A reply you have not seen reads a little stronger. */
.history-row[data-status="unread"] .history-titleText { font-weight: 600; }

/*
 * The sidebar's loading mark while a conversation is working: the "ASCII braille" spinner ⣾⣽⣻⢿⡿⣟⣯⣷. A braille cell of
 * eight dots (two columns of four) with one dot missing, the gap stepping down the left column, across the bottom and up the
 * right, one dot per eighth of the cycle (125 ms of 1 s). Drawn as dots rather than typed as braille characters, so it looks
 * the same in every font, takes the text colour and needs no script. It sits centred in the same 14 x 16 px box as the other
 * status marks, so a row never shifts when its status changes.
 *
 * Each dot is dark for one frame of the eight. They all run one keyframe ("dark for the first eighth"), started at
 * --gap eighths into the cycle, which is the frame in which that dot is the missing one. `step-end` holds each value.
 */
.status-braille {
  --cycle: 1s;
  display: inline-grid;
  grid-auto-flow: column;
  /* 2.5px dots on a 4px pitch: light enough to sit beside 13px text, where 3px dots read as a heavy clump. */
  grid-template-rows: repeat(4, 2.5px);
  grid-template-columns: repeat(2, 2.5px);
  gap: 1.5px;
  place-content: center;
  width: 0.875rem;
  height: 1rem;
}

.status-braille > i {
  display: block;
  border-radius: 9999px;
  background: currentColor;
  animation: braille-gap var(--cycle) step-end infinite;
  animation-delay: calc(var(--gap) * var(--cycle) / 8);
}

/* Left column top to bottom (dots 1, 2, 3, 7), then right column top to bottom (dots 4, 5, 6, 8); --gap is the frame in which each is missing. */
.status-braille > i:nth-child(1) { --gap: 0; }
.status-braille > i:nth-child(2) { --gap: 1; }
.status-braille > i:nth-child(3) { --gap: 2; }
.status-braille > i:nth-child(4) { --gap: 3; }
.status-braille > i:nth-child(5) { --gap: 7; }
.status-braille > i:nth-child(6) { --gap: 6; }
.status-braille > i:nth-child(7) { --gap: 5; }
.status-braille > i:nth-child(8) { --gap: 4; }

